import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [data, setData] = useState(null);
  const [selectedStock, setSelectedStock] = useState("RELIANCE.NS");
  const [loading, setLoading] = useState(false);

  // Popular Indian Stocks List
  const stockList = [
    { name: "Reliance Industries", symbol: "RELIANCE.NS" },
    { name: "TCS", symbol: "TCS.NS" },
    { name: "HDFC Bank", symbol: "HDFCBANK.NS" },
    { name: "Infosys", symbol: "INFY.NS" },
    { name: "ICICI Bank", symbol: "ICICIBANK.NS" },
    { name: "SBI", symbol: "SBIN.NS" },
    { name: "Tata Motors", symbol: "TATAMOTORS.NS" },
    { name: "Bharti Airtel", symbol: "AIRTEL.NS" }
  ];

  const fetchData = (symbol) => {
    setLoading(true);
    axios.get(`http://localhost:8000/api/analyze?tickers=${symbol}`)
      .then(res => {
        setData(res.data);
        setLoading(false);
      })
      .catch(err => {
        console.error(err);
        setLoading(false);
      });
  };

  // Dropdown change aagum pothu trigger aagum
  useEffect(() => {
    fetchData(selectedStock);
  }, [selectedStock]);

  return (
    <div style={{ backgroundColor: '#0e1117', color: '#c9d1d9', minHeight: '100vh', padding: '20px', fontFamily: 'monospace' }}>
      
      <div style={{ borderBottom: '1px solid #30363d', paddingBottom: '10px' }}>
        <h2 style={{ color: '#58a6ff' }}>🛡️ QuantShield AI Portfolio Optimizer</h2>
      </div>

      {/* Dropdown Selector Section */}
      <div style={{ margin: '30px 0', background: '#161b22', padding: '20px', borderRadius: '8px', border: '1px solid #30363d' }}>
        <label style={{ marginRight: '15px', fontWeight: 'bold', fontSize: '18px' }}>📁 Select Asset from Universe:</label>
        <select 
          value={selectedStock} 
          onChange={(e) => setSelectedStock(e.target.value)}
          style={{ 
            background: '#0d1117', color: 'white', border: '1px solid #58a6ff', 
            padding: '10px', borderRadius: '5px', width: '300px', cursor: 'pointer', fontSize: '16px'
          }}
        >
          {stockList.map((stock) => (
            <option key={stock.symbol} value={stock.symbol}>
              {stock.name} ({stock.symbol})
            </option>
          ))}
        </select>
        {loading && <span style={{ marginLeft: '15px', color: '#f1e05a' }}>⚡ Analyzing...</span>}
      </div>

      {data && (
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1.5fr', gap: '20px' }}>
          
          {/* Market Analysis (Streamlit 094319 Style) */}
          <div style={{ background: '#161b22', padding: '20px', borderRadius: '8px', border: '1px solid #30363d' }}>
            <h3 style={{ color: '#ff4b4b' }}>📊 Market Analysis: {selectedStock}</h3>
            <div style={{ lineHeight: '3', fontSize: '18px' }}>
              <div style={{ borderBottom: '1px solid #21262d' }}>Sharpe Ratio: <b style={{float: 'right', color: '#58a6ff'}}>{data.sharpe_ratio || data.cps_score}</b></div>
              <div style={{ borderBottom: '1px solid #21262d' }}>Volatility: <b style={{float: 'right', color: '#f85149'}}>{data.volatility || '0.22'}</b></div>
              <div style={{ borderBottom: '1px solid #21262d' }}>Market Regime: <b style={{float: 'right'}}>{data.regime}</b></div>
              <div style={{ borderBottom: '1px solid #21262d' }}>BSI Score: <b style={{float: 'right', color: '#d2a8ff'}}>{data.bsi_score}</b></div>
            </div>

            <div style={{ 
              marginTop: '40px', padding: '15px', textAlign: 'center', borderRadius: '5px',
              background: data.regime === "STRESS" ? '#4a151b' : '#0d1117',
              border: '1px solid #f85149'
            }}>
              🛡️ GHOST HEDGE: {data.regime === "STRESS" ? "ACTIVE" : "MONITORING"}
            </div>
          </div>

          {/* Forecasting Logic (The ₹10,000 Step) */}
          <div style={{ background: '#161b22', padding: '20px', borderRadius: '8px', border: '1px solid #30363d' }}>
            <h3 style={{ color: '#58a6ff' }}>🎲 Monte Carlo Risk Forecast</h3>
            <div style={{ marginTop: '20px' }}>
              <div style={{ background: '#0d1117', padding: '20px', borderRadius: '10px', marginBottom: '20px', borderLeft: '5px solid #238636' }}>
                <p style={{ margin: 0, color: '#8b949e' }}>Expected Value (on ₹10,000 Invested)</p>
                <h1 style={{ color: '#3fb950', fontSize: '3rem' }}>₹{data.forecast.expected}</h1>
              </div>
              <div style={{ background: '#0d1117', padding: '20px', borderRadius: '10px', borderLeft: '5px solid #f85149' }}>
                <p style={{ margin: 0, color: '#8b949e' }}>Worst Case Scenario (Risk)</p>
                <h1 style={{ color: '#f85149', fontSize: '3rem' }}>₹{data.forecast.worst_case}</h1>
              </div>
            </div>

            <div style={{ 
              marginTop: '30px', padding: '20px', textAlign: 'center', 
              borderRadius: '10px', background: data.decision === "BUY" ? '#238636' : '#f85149',
              fontSize: '22px', fontWeight: 'bold'
            }}>
              🤖 AI VERDICT: {data.decision}
            </div>
          </div>

        </div>
      )}
    </div>
  );
}

export default App;
